<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class PracticeDistributionController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->hasRole('practice_head')||$r->user()->canDo('practice.manage'),403);}
public function show(Request $r,$campaign){$this->manage($r);$c=DB::table('practice_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->where('c.id',$campaign)->select('c.*','g.name as group_name')->first();abort_if(!$c,404);$students=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->leftJoin('practice_placements as p',function($j)use($campaign){$j->on('p.student_id','=','s.id')->where('p.practice_campaign_id','=',$campaign);})->where(['m.academic_period_id'=>$c->academic_period_id,'m.study_group_id'=>$c->study_group_id])->select('s.id','s.last_name','s.first_name','s.middle_name','p.id placement_id','p.organization_name','p.status','p.attestation_grade')->orderBy('s.last_name')->get();$orgs=DB::table('practice_campaign_organizations as co')->join('practice_organizations as o','o.id','=','co.practice_organization_id')->where('co.practice_campaign_id',$campaign)->select('co.*','o.name')->get();$allOrgs=DB::table('practice_organizations')->where('status','active')->orderBy('name')->get();return view('practice-office.distribution',compact('c','students','orgs','allOrgs'));}
public function attachOrg(Request $r,$campaign){$this->manage($r);$d=$r->validate(['practice_organization_id'=>'required|exists:practice_organizations,id','practice_agreement_id'=>'nullable|exists:practice_agreements,id','capacity'=>'nullable|integer|min:1']);DB::table('practice_campaign_organizations')->updateOrInsert(['practice_campaign_id'=>$campaign,'practice_organization_id'=>$d['practice_organization_id']],$d+['updated_at'=>now(),'created_at'=>now()]);return back();}
public function distribute(Request $r,$campaign){$this->manage($r);$c=DB::table('practice_campaigns')->find($campaign);abort_if(!$c,404);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['student_ids'=>'required|array|min:1','student_ids.*'=>'exists:students,id','practice_organization_id'=>'required|exists:practice_organizations,id','supervisor_org'=>'nullable|string|max:255']);$o=DB::table('practice_organizations')->find($d['practice_organization_id']);$ag=DB::table('practice_agreements')->where('practice_organization_id',$o->id)->where('status','active')->where('valid_from','<=',$c->starts_on)->where(function($q)use($c){$q->whereNull('valid_to')->orWhere('valid_to','>=',$c->ends_on);})->orderByDesc('signed_on')->first();DB::transaction(function()use($d,$c,$o,$ag){foreach($d['student_ids'] as $sid){$id=DB::table('practice_placements')->insertGetId(['practice_campaign_id'=>$c->id,'academic_period_id'=>$c->academic_period_id,'student_id'=>$sid,'practice_type'=>$c->practice_type,'organization_name'=>$o->name,'practice_organization_id'=>$o->id,'practice_agreement_id'=>$ag->id??null,'supervisor_teacher_id'=>$c->supervisor_teacher_id,'supervisor_org'=>$d['supervisor_org']??null,'starts_on'=>$c->starts_on,'ends_on'=>$c->ends_on,'status'=>'planned','created_at'=>now(),'updated_at'=>now()]);foreach(['direction','individual_task','briefing','diary','report','characteristic','attestation'] as $type)DB::table('practice_document_checks')->insert(['practice_placement_id'=>$id,'document_type'=>$type,'status'=>'missing','created_at'=>now(),'updated_at'=>now()]);}});return back();}
public function control(Request $r,$placement){$this->manage($r);$x=DB::table('practice_placements')->find($placement);abort_if(!$x,404);$d=$r->validate(['visited_at'=>'required|date','control_type'=>'required|in:visit,call,remote','result'=>'required|string|max:5000','action_required'=>'nullable|string|max:5000','control_on'=>'nullable|date']);DB::table('practice_control_visits')->insert($d+['practice_placement_id'=>$placement,'teacher_id'=>$r->user()->teacher_id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function briefing(Request $r,$placement){$this->manage($r);$d=$r->validate(['type'=>'required|string|max:100','briefed_on'=>'required|date','instructor'=>'required|string|max:255','note'=>'nullable|string|max:3000']);DB::table('practice_briefings')->insert($d+['practice_placement_id'=>$placement,'confirmed'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('practice_document_checks')->updateOrInsert(['practice_placement_id'=>$placement,'document_type'=>'briefing'],['status'=>'complete','checked_at'=>now(),'checked_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function document(Request $r,$placement){$this->manage($r);$d=$r->validate(['document_type'=>'required|in:direction,individual_task,briefing,diary,report,characteristic,attestation','status'=>'required|in:missing,submitted,complete,revision','note'=>'nullable|string|max:2000']);DB::table('practice_document_checks')->updateOrInsert(['practice_placement_id'=>$placement,'document_type'=>$d['document_type']],['status'=>$d['status'],'note'=>$d['note']??null,'checked_at'=>now(),'checked_by'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function debts(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('practice_placements as p')->join('students as s','s.id','=','p.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('p.academic_period_id',$p->id)->where(function($q){$q->whereNull('p.attestation_grade')->orWhere('p.attestation_grade','')->orWhereExists(function($x){$x->select(DB::raw(1))->from('practice_document_checks as d')->whereColumn('d.practice_placement_id','p.id')->whereIn('d.status',['missing','revision']);});})->select('p.*','s.last_name','s.first_name','g.name as group_name')->orderBy('g.name')->orderBy('s.last_name')->get();return view('practice-office.debts',compact('rows'));}
}